    def lowarr_for(self, low):
        arr = [0] * self.narcs
        for f in range(self.F):
            arr[self.flow_arc[f]] = low[f]
        return arr

    # ---------------- cut -------------------------------------------------
    def cut_for(self, idx):
        """Node subset proving the next ratio of the public set infeasible."""
        cands = self.rset
        if idx + 1 >= len(cands):
            return None
        next_low = self.lowers(cands[idx + 1])
        ok, seen = self.feasible(next_low, need_cut=True)
        if ok or seen is None:
            return None
        if not self.verify_cut(seen, next_low):
            return None
        self.cut_low = next_low
        self.cut_ratio = cands[idx + 1]
        return seen

    def verify_cut(self, cut, low):
        inside = [False] * self.K
        for v in cut:
            if v < 0 or v >= self.K:
                return False
            inside[v] = True
        lowarr = self.lowarr_for(low)
        ein = 0
        eout = 0
        tail = self.tail
        head = self.head
        capa = self.capa
        for i in range(self.narcs):
            u = tail[i]
            v = head[i]
            if inside[u]:
                if not inside[v]:
                    eout += capa[i]
            elif inside[v]:
                ein += lowarr[i]
        return ein > eout

