    def verify(self, ratio, low, cut):
        S, J, F, G, K = self.S, self.J, self.F, self.G, self.K
        flow = self.arcflow
        tail = self.tail
        head = self.head
        capa = self.capa
        lowarr = self.lowarr_for(low)
        if len(flow) != self.narcs:
            return False
        bal = [0] * K
        for i in range(self.narcs):
            x = flow[i]
            if x < 0 or x > capa[i] or x < lowarr[i]:
                return False
            bal[tail[i]] -= x
            bal[head[i]] += x
        for v in range(K):
            if bal[v]:
                return False
        pairs = self.pairs
        for t in range(len(pairs)):
            s, j = pairs[t]
            want = 1 if self.assignment[j] == s else 0
            if flow[self.dense_start + t] != want:
                return False
        for j in range(J):
            s = self.assignment[j]
            if s >= 0 and (not self.passes[j] or s < self.elo[j]
                           or s > self.ehi[j]):
                return False
        used = [0] * S
        cnt = {}
        for j in range(J):
            s = self.assignment[j]
            if s >= 0:
                used[s] += 1
                cnt[self.wflow[j]] = cnt.get(self.wflow[j], 0) + 1
        for f in range(F):
            if cnt.get(f, 0) != self.nf[f]:
                return False
        if ratio != Fraction(1, 1):
            r = Fraction(1, 1)
            for f in range(F):
                fr = Fraction(self.nf[f], self.target[f])
                if fr < r:
                    r = fr
            if r != ratio:
                return False
        else:
            for f in range(F):
                if self.nf[f] < self.target[f]:
                    return False
        if not self.check_potentials(self.pot, low):
            return False
        if ratio < 1:
            if cut is None:
                return False
            if not self.verify_cut(cut, self.cut_low):
                return False
        elif cut is not None:
            return False
        return True

    def report(self):
        return metrics.selected_report(self.flows, self.windows, self.preds,
                                       self.assignment)


